from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_PERCENT = 0.50

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option_symbol = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.Consolidate(self.spy, timedelta(minutes=5), self.OnFiveMinuteBar)

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.pending_entry_symbol = None
        self.time_stop_sent = False
        self.blocked_entry_date = None

    def OnData(self, data):
        self._flatten_unexpected_spy_position()

        if self.held_contract is None:
            return

        if self.held_expiry is not None and self.Time.date() >= self.held_expiry:
            self.blocked_entry_date = self.Time.date()
            self.Debug(f"Expiration safeguard for {self.held_contract}")
            self._submit_exit("expiration safeguard", True)
            return

        if (
            not self.time_stop_sent
            and self.Time.date() == self._previous_spy_trading_day(self.held_expiry)
            and self.Time.time() == time(15, 45)
        ):
            self.time_stop_sent = True
            self.Debug(f"Time-stop exit for {self.held_contract}")
            self._submit_exit("time stop", False)
            return

        if self.entry_price is None or self._has_open_exit_order():
            return

        midpoint = self._option_midpoint_from_slice(data, self.held_contract)
        if midpoint is None:
            return

        if midpoint >= self.entry_price * (1 + self.PROFIT_TARGET_PERCENT):
            self.Debug(f"Profit-target exit for {self.held_contract} at midpoint {midpoint:.2f}")
            self._submit_exit("profit target", True)

    def OnFiveMinuteBar(self, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )
        if not bullish_cross:
            return

        bar_time = bar.EndTime.time()
        if bar_time < time(9, 45) or bar_time > time(14, 30):
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_ticket is not None:
            return

        self._try_enter_from_current_slice(bar.Close)

    def _try_enter_from_current_slice(self, spy_price):
        data = self.CurrentSlice
        if data is None or data.OptionChains is None or data.OptionChains.Count == 0:
            self.Debug("Skipped entry: no SPY option chain in current Slice")
            return

        today = self.Time.date()
        contracts = []

        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right == OptionRight.Call:
                    contracts.append(contract)

        eligible = [
            contract for contract in contracts
            if (contract.Expiry.date() - today).days >= 7
        ]
        if not eligible:
            self.Debug("Skipped entry: no call expiration at least 7 calendar days away")
            return

        expiry = min(contract.Expiry.date() for contract in eligible)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiry and contract.Strike >= minimum_strike
        ]
        if not candidates:
            self.Debug(f"Skipped entry: no qualifying call at expiry {expiry}")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.pending_entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {expiry}, "
            f"strike {selected.Strike}"
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
                self.held_contract = self.pending_entry_symbol
                self.held_expiry = self.held_contract.ID.Date.date()
                self.entry_price = order_event.FillPrice
                self.time_stop_sent = False

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Entry filled: {self.held_contract} at {self.entry_price:.2f}"
                    )
                    self.entry_ticket = None
                    self.pending_entry_symbol = None

            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry canceled or invalid: {self.pending_entry_symbol}")
                self.entry_ticket = None
                self.pending_entry_symbol = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract} at {order_event.FillPrice:.2f}")
                self.held_contract = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_ticket = None
                self.time_stop_sent = False

        if (
            order_event.Symbol == self.spy
            and order_event.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]
        ):
            self._flatten_unexpected_spy_position()

    def _submit_exit(self, reason, cancel_existing):
        if self.held_contract is None:
            return

        if cancel_existing:
            for order in self.Transactions.GetOpenOrders(self.held_contract):
                if order.Direction == OrderDirection.Sell:
                    self.Transactions.CancelOrder(order.Id, f"Replacing exit: {reason}")

        if self._has_open_exit_order():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}")

    def _has_open_exit_order(self):
        if self.held_contract is None:
            return False

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Direction == OrderDirection.Sell:
                return True
        return False

    def _option_midpoint_from_slice(self, data, symbol):
        for chain in data.OptionChains.Values:
            if chain.Contracts.ContainsKey(symbol):
                contract = chain.Contracts[symbol]
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        if data.QuoteBars.ContainsKey(symbol):
            quote = data.QuoteBars[symbol]
            if quote.Bid is not None and quote.Ask is not None:
                bid = quote.Bid.Close
                ask = quote.Ask.Close
                if bid > 0 and ask > 0:
                    return (bid + ask) / 2.0

        return None

    def _previous_spy_trading_day(self, expiration_date):
        date = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(datetime.combine(date, time.min)):
            date -= timedelta(days=1)

        return date

    def _flatten_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(f"Unexpected SPY exercise/assignment position: {quantity}; liquidating")
            self.MarketOrder(self.spy, -quantity)

