        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(lambda u: u.IncludeWeeklys().Strikes(-200, 200).Expiration(0, 365))

        self.option_symbol = self.option.Symbol
        self.five_minute_closes = deque(maxlen=20)
        self.minute_buffer = []
        self.expected_minute_end = None
        self.session_date = None

        self.held_symbol = None
        self.held_expiry = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_block_date = None

        self.profit_target_multiple = 1.25

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_protection()

        if self.held_symbol is not None and self.entry_fill_price is not None:
            self._evaluate_exit(slice)

        if self.entry_order_id is None and self.held_symbol is None:
            self._update_five_minute_consolidation(slice)

    def _update_five_minute_consolidation(self, slice):
        if self.spy.Symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy.Symbol]
        end = minute_bar.EndTime
        current_date = end.date()

        if self.session_date != current_date:
            self.session_date = current_date
            self.minute_buffer = []
            self.expected_minute_end = None

        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        if self.expected_minute_end is not None and end != self.expected_minute_end:
            self.minute_buffer = []

        self.minute_buffer.append(minute_bar)
        self.expected_minute_end = end + timedelta(minutes=1)

        if end.minute % 5 != 0:
            return

        if len(self.minute_buffer) != 5:
            self.minute_buffer = []
            return

        five_minute_close = self.minute_buffer[-1].Close
        self.minute_buffer = []

        prior = list(self.five_minute_closes)
        self.five_minute_closes.append(five_minute_close)

        if len(prior) < 20:
            return

        previous_fast = sum(prior[-5:]) / 5.0
        previous_slow = sum(prior) / 20.0
        current = list(self.five_minute_closes)
        current_fast = sum(current[-5:]) / 5.0
        current_slow = sum(current) / 20.0

        bullish_cross = previous_fast <= previous_slow and current_fast > current_slow
        eligible_time = time(9, 45) <= end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter_from_current_slice()

    def _try_enter_from_current_slice(self):
        if self.Time.date() == self.expiration_block_date:
            return

        slice = self.CurrentSlice
        if slice is None or self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiry at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped: no qualifying call at selected expiry.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.held_expiry = selected.Expiry
        self.Debug(
            f"{self.Time}: Entry submitted: {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def _evaluate_exit(self, slice):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        if self._is_pre_expiry_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        contract = self._current_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * self.profit_target_multiple:
            self._submit_exit("profit target")

    def _current_contract(self, slice, symbol):
        if slice is None:
            return None

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _is_pre_expiry_time_stop(self):
        if self.held_expiry is None:
            return False

        previous_trading_day = self.Securities[self.spy.Symbol].Exchange.Hours.GetPreviousTradingDay(
            self.held_expiry
        )

        return (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        )

    def _handle_expiration_protection(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.expiration_block_date = self.Time.date()
            if self.Portfolio[self.held_symbol].Invested:
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self.held_symbol is None or not self.Portfolio[self.held_symbol].Invested:
            return

        if self.exit_order_id is not None:
            open_ids = {order.Id for order in self.Transactions.GetOpenOrders(self.held_symbol)}
            if self.exit_order_id in open_ids:
                return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[self.held_symbol].Quantity
        ticket = self.MarketOrder(self.held_symbol, quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self.held_symbol}: {reason}.")

    def _handle_unexpected_spy_position(self):
        if not self.Portfolio[self.spy.Symbol].Invested:
            return

        open_spy_orders = self.Transactions.GetOpenOrders(self.spy.Symbol)
        if not open_spy_orders:
            self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position; liquidating.")
            self.MarketOrder(self.spy.Symbol, -self.Portfolio[self.spy.Symbol].Quantity)

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self.entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_symbol = orderEvent.Symbol
                self.entry_fill_price = orderEvent.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled: {orderEvent.Symbol} at {orderEvent.FillPrice}."
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.held_expiry = None
                self.Debug(f"{self.Time}: Entry order did not fill: {orderEvent.Symbol}.")

        if orderEvent.OrderId == self.exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled: {orderEvent.Symbol} at {orderEvent.FillPrice}."
                )
                self.held_symbol = None
                self.held_expiry = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

