        prior_slow = self.slow.current.value

        self.fast.update(bar.end_time, bar.close)
        self.slow.update(bar.end_time, bar.close)

        current_fast = self.fast.current.value
        current_slow = self.slow.current.value

        if prior_fast <= prior_slow and current_fast > current_slow:
            bar_end = bar.end_time
            if (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)) and \
               (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)):
                self.pending_crossover_time = bar_end

