        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.expiry.date() == expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(f"{crossover_time}: skipped entry; no qualifying call at {expiry}.")
            return

        selected = sorted(candidates, key=lambda x: (x.strike, str(x.symbol)))[0]
        self.entry_ticket = self.market_order(selected.symbol, 1)
