        if self.entry_ticket is None:
            return False
        return self.entry_ticket.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        )

    def _has_open_exit_order(self):
        if self.exit_ticket is None:
            return False
        return self.exit_ticket.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        )

    def _has_option_position(self):
        return any(
            security.symbol.security_type == SecurityType.OPTION and security.holdings.invested
            for security in self.securities.values()
        )

    def _liquidate_unexpected_spy(self):
        if self.portfolio[self.spy].invested:
            self.debug("Unexpected SPY exercise or assignment position detected; liquidating SPY.")
            self.market_order(self.spy, -self.portfolio[self.spy].quantity)

