from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(timedelta(0), timedelta(days=730))
        )

        self.closes = deque(maxlen=21)
        self.bucket_key = None
        self.bucket_minutes = set()
        self.bucket_close = None

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.no_entry_date = None
        self.spy_liquidation_order_id = None

        # A 50% gain from the filled entry price is the profit target.
        self.profit_target_multiple = 1.50

    def OnData(self, data):
        if self._liquidate_unexpected_spy_position():
            return

        self._handle_expiration_safety()

        if self.held_contract is not None:
            self._check_time_stop()
            self._check_profit_target(data)

        if data.Bars.ContainsKey(self.spy):
            self._update_five_minute_bar(data.Bars[self.spy], data)

    def _update_five_minute_bar(self, minute_bar, data):
        end_time = minute_bar.EndTime
        clock = end_time.time()

        if clock < time(9, 31) or clock > time(16, 0):
            return

        end_minute = clock.hour * 60 + clock.minute
        bucket_end_minute = ((end_minute + 4) // 5) * 5
        key = (end_time.date(), bucket_end_minute)

        if self.bucket_key != key:
            self.bucket_key = key
            self.bucket_minutes = set()
            self.bucket_close = None

        self.bucket_minutes.add(end_minute)
        self.bucket_close = minute_bar.Close

        if end_minute != bucket_end_minute:
            return

        expected_minutes = set(range(bucket_end_minute - 4, bucket_end_minute + 1))
        if self.bucket_minutes != expected_minutes:
            return

        self.closes.append(self.bucket_close)
        self._evaluate_crossover(end_time, data)

    def _evaluate_crossover(self, bar_end_time, data):
        if len(self.closes) < 21:
            return

        current_clock = bar_end_time.time()
        if current_clock < time(9, 45) or current_clock > time(14, 30):
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.no_entry_date == self.Time.date():
            return

        prices = list(self.closes)
        prior_fast = sum(prices[-6:-1]) / 5.0
        prior_slow = sum(prices[-21:-1]) / 20.0
        current_fast = sum(prices[-5:]) / 5.0
        current_slow = sum(prices[-20:]) / 20.0

        if not (prior_fast <= prior_slow and current_fast > current_slow):
            return

        self._submit_entry_from_chain(data)

    def _submit_entry_from_chain(self, data):
        if not data.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Entry skipped: no SPY option chain in Slice.")
            return

        chain = data.OptionChains[self.option_symbol]
        algorithm_date = self.Time.date()
        spot = self.Securities[self.spy].Price

        if spot <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - algorithm_date).days >= 7
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = 1.01 * spot

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} expiry {selected_expiry}, "
            f"strike {selected.Strike}."
        )

    def _check_profit_target(self, data):
        if self.entry_fill_price is None or self.entry_fill_price <= 0:
            return

        if self.exit_order_id is not None:
            return

        if not data.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = data.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * self.profit_target_multiple:
            self._submit_option_exit("profit target")

    def _check_time_stop(self):
        if self.held_contract is None or self.expiration_date is None:
            return

        prior_trading_day = self._previous_spy_trading_day(self.expiration_date)
        if prior_trading_day is None:
            return

        if self.Time.date() == prior_trading_day and self.Time.time() == time(15, 45):
            self._submit_option_exit("pre-expiration time stop")

    def _handle_expiration_safety(self):
        if self.held_contract is None or self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            self.no_entry_date = self.Time.date()
            self._submit_option_exit("expiration safety")

    def _previous_spy_trading_day(self, expiration_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiration_date - timedelta(days=1)

        for _ in range(10):
            if exchange_hours.IsDateOpen(candidate):
                return candidate
            candidate -= timedelta(days=1)

        return None

    def _submit_option_exit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            ticket = self.Transactions.GetOrderTicket(order.Id)
            if ticket is not None:
                ticket.Cancel("Replacing with option exit market order.")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return False

        if self.spy_liquidation_order_id is None:
            ticket = self.MarketOrder(self.spy, -quantity)
            self.spy_liquidation_order_id = ticket.OrderId
            self.Debug("Unexpected SPY exercise/assignment position: liquidation submitted.")

        return True

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self.spy:
            if order_event.OrderId == self.spy_liquidation_order_id and \
                    order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.spy_liquidation_order_id = None
            return

        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry order closed without a fill.")
            return

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity == 0:
                    self.Debug(f"Exit filled: {self.held_contract}.")
                    self.held_contract = None
                    self.entry_fill_price = None
                    self.expiration_date = None
                    self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

