            return

        contract = self._find_contract_in_slice(data, self.held_contract)
        if contract is None:
            return

        bid = float(contract.bid_price)
        ask = float(contract.ask_price)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1 + self.profit_target_percent)

        if midpoint >= target:
            self._submit_exit("profit target")

    def _time_stop(self):
        if self.held_contract is None:
            return

        holding = self.portfolio[self.held_contract]
        if holding.quantity == 0:
            return

        expiry = self.held_contract.id.date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if self.time.date() == previous_trading_day:
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_safety(self):
        if self.held_contract is None:
            return

        holding = self.portfolio[self.held_contract]
        if holding.quantity == 0:
            return

        expiry = self.held_contract.id.date.date()
        if self.time.date() >= expiry:
            self.no_entry_date = self.time.date()
            self._submit_exit("expiration safety liquidation")

    def _handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy].quantity
        if quantity == 0:
            return

        open_orders = self.transactions.get_open_orders(self.spy)
        if not open_orders:
            self.market_order(self.spy, -quantity)
            self.debug("Unexpected SPY exercise/assignment position liquidated.")

    def _submit_exit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.portfolio[self.held_contract].quantity
        if quantity == 0:
            return

        for order in self.transactions.get_open_orders(self.held_contract):
            ticket = self.transactions.get_order_ticket(order.id)
            if ticket is not None:
                ticket.cancel("Replacing with market exit")

        ticket = self.market_order(self.held_contract, -quantity)
        self.exit_order_id = ticket.order_id
        self.debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _entry_order_is_open(self):
        if self.entry_order_id is None:
            return False

        for order in self.transactions.get_open_orders():
            if order.id == self.entry_order_id:
                return True

        self.entry_order_id = None
        return False

    def _exit_order_is_open(self):
        if self.exit_order_id is None:
            return False

        for order in self.transactions.get_open_orders():
            if order.id == self.exit_order_id:
                return True

        self.exit_order_id = None
        return False

    def _find_contract_in_slice(self, data, symbol):
        for chain in data.option_chains.values():
            for contract in chain:
                if contract.symbol == symbol:
                    return contract
        return None

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def on_order_event(self, order_event):
        if self.entry_order_id == order_event.order_id:
            if order_event.status == OrderStatus.FILLED:
                self.held_contract = order_event.symbol
                self.entry_price = float(order_event.fill_price)
                self.entry_order_id = None
                self.debug(
                    f"Entry filled: {order_event.symbol} at {order_event.fill_price}."
                )
            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                self.entry_order_id = None
                self.debug(f"Entry closed without fill: {order_event.symbol}.")

        if self.exit_order_id == order_event.order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"Exit filled: {order_event.symbol} at {order_event.fill_price}."
                )
                if self.portfolio[order_event.symbol].quantity == 0:
                    self.held_contract = None
                    self.entry_price = None
                    self.exit_order_id = None
            elif order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                self.exit_order_id = None

