        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.block_entries_on_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour, end_time.minute) >= (9, 45) and
            (end_time.hour, end_time.minute) <= (14, 30)
        )

        if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
            self.pending_entry_time = end_time

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.active_contract is not None:
            expiry_date = self.active_contract.ID.Date.date()

            if self.Time.date() >= expiry_date:
                self.block_entries_on_date = self.Time.date()
                if self.Portfolio[self.active_contract].Invested:
                    self.SubmitExit("expiration processing")
                return

            if self.Portfolio[self.active_contract].Invested:
                if self.IsTradingDayBeforeExpiry(expiry_date):
                    if (self.Time.hour, self.Time.minute) == (15, 45):
                        self.SubmitExit("pre-expiration time stop")
                        return

                self.CheckProfitTarget(slice)

        if self.pending_entry_time is not None:
            signal_time = self.pending_entry_time
            self.pending_entry_time = None

            if signal_time != self.Time:
                return

            if self.block_entries_on_date == self.Time.date():
                return

            if self.HasOpenEntryOrder() or self.HasOptionHolding():
                return

            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: skipped entry - no SPY option chain")
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug(f"{self.Time}: skipped entry - invalid SPY price")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug(f"{self.Time}: skipped entry - no expiration at least 7 calendar days away")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry - no qualifying call at selected expiration")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.active_contract = selected.Symbol
        self.entry_fill_price = None
        self.Debug(f"{self.Time}: entry submitted {selected.Symbol}")

    def CheckProfitTarget(self, slice):
        if self.entry_fill_price is None or self.exit_order_id is not None:
            return

        if self.active_contract not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.active_contract]
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_fill_price * (1.0 + self.PROFIT_TARGET_PERCENT)

        if midpoint >= target_price:
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.active_contract is None or not self.Portfolio[self.active_contract].Invested:
            return

        if self.exit_order_id is not None:
            order = self.Transactions.GetOrderById(self.exit_order_id)
            if order is not None and order.Status in (OrderStatus.New, OrderStatus.Submitted):
                self.Transactions.CancelOrder(self.exit_order_id)

        quantity = -self.Portfolio[self.active_contract].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.active_contract, quantity)
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: exit submitted {self.active_contract} - {reason}")

    def IsTradingDayBeforeExpiry(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return self.Time.date() == candidate

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in (OrderStatus.New, OrderStatus.Submitted)

    def HasOptionHolding(self):
        return self.active_contract is not None and self.Portfolio[self.active_contract].Invested

    def HandleUnexpectedEquityPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        open_orders = self.Transactions.GetOpenOrders(self.spy)
        if len(open_orders) == 0:
            quantity = -self.Portfolio[self.spy].Quantity
            self.MarketOrder(self.spy, quantity)
            self.Debug(f"{self.Time}: unexpected SPY exercise/assignment position liquidated")

    def OnOrderEvent(self, order_event):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: entry filled {order_event.Symbol} @ {order_event.FillPrice}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: entry canceled/invalid {order_event.Symbol}")
                self.entry_order_id = None
                self.active_contract = None
                self.entry_fill_price = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: exit filled {order_event.Symbol} @ {order_event.FillPrice}"
                )
                self.exit_order_id = None
                self.active_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

