from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.Strikes(-100, 100)
                                    .Expiration(timedelta(0), timedelta(730))
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.minute_ends = RollingWindow[datetime](5)
        self.minute_closes = RollingWindow[float](5)

        self.held_contract = None
        self.held_expiry = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_order_id = None
        self.spy_liquidation_order_id = None
        self.no_entry_date = None

        # Adjust this strategy parameter if a different target is desired.
        self.profit_target_multiple = 1.20

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        if self.held_contract is not None:
            self._handle_expiration_processing()
            self._handle_time_exit()
            self._handle_profit_target(data)

        if not data.Bars.ContainsKey(self.spy):
            return

        spy_bar = data.Bars[self.spy]
        bar_end = spy_bar.EndTime

        if not self._is_regular_session_minute(bar_end):
            return

        self.minute_ends.Add(bar_end)
        self.minute_closes.Add(spy_bar.Close)

        if bar_end.minute % 5 != 0:
            return

        if not self._has_complete_five_minute_bar(bar_end):
            return

        had_ready_averages = self.fast.IsReady and self.slow.IsReady
        prior_fast = self.fast.Current.Value if had_ready_averages else None
        prior_slow = self.slow.Current.Value if had_ready_averages else None

        self.fast.Update(bar_end, spy_bar.Close)
        self.slow.Update(bar_end, spy_bar.Close)

        bullish_crossover = (
            had_ready_averages
            and self.fast.IsReady
            and self.slow.IsReady
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

        if bullish_crossover:
            self._try_enter(data, bar_end)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.held_contract = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_order_id = None
                self.Debug(
                    f"Entered {self.held_contract}: fill {self.entry_price:.2f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exited {order_event.Symbol}: fill {order_event.FillPrice:.2f}"
                )
                self.held_contract = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_order_id = None

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.spy_liquidation_order_id = None

    def _try_enter(self, data: Slice, bar_end: datetime):
        if not (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)):
            return
        if bar_end.hour > 14 or (bar_end.hour == 14 and bar_end.minute > 30):
            return
        if self.no_entry_date == self.Time.date():
            return
        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if not data.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no SPY option chain in current Slice")
            return

        chain = data.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        spot = self.Securities[self.spy].Price

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - current_date).days >= 7
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away")
            return

        expiration = eligible_expirations[0]
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration")
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, strike {selected.Strike}, expiry {expiration}"
        )

    def _handle_profit_target(self, data: Slice):
        if self.exit_order_id is not None or self.entry_price is None:
            return
        if not data.OptionChains.ContainsKey(self.option_symbol):
            return

        contract = None
        for candidate in data.OptionChains[self.option_symbol]:
            if candidate.Symbol == self.held_contract:
                contract = candidate
                break

        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * self.profit_target_multiple:
            self._submit_exit("profit target")

    def _handle_time_exit(self):
        if self.held_contract is None or self.held_expiry is None:
            return
        if self.exit_order_id is not None:
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.held_expiry
        )

        if (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _handle_expiration_processing(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.no_entry_date = self.Time.date()
            if self.exit_order_id is None:
                self._submit_exit("expiration processing")

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted for {self.held_contract}: {reason}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug(
            f"Unexpected SPY position from exercise/assignment; liquidation submitted: {quantity}"
        )

    def _is_regular_session_minute(self, bar_end: datetime) -> bool:
        return (
            (bar_end.hour == 9 and bar_end.minute >= 31)
            or (bar_end.hour >= 10 and bar_end.hour < 16)
            or (bar_end.hour == 16 and bar_end.minute == 0)
        )

    def _has_complete_five_minute_bar(self, bar_end: datetime) -> bool:
        if self.minute_ends.Count < 5 or self.minute_closes.Count < 5:
            return False

        for index in range(5):
            expected = bar_end - timedelta(minutes=index)
            if self.minute_ends[index] != expected:
                return False

        return True
